import { useEffect, useState } from 'react'
import { navigation, profile } from '../data/profile'

export function Navigation() {
  const [scrolled, setScrolled] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)
  const [active, setActive] = useState(navigation[0].id)

  useEffect(() => {
    const onScroll = () => {
      setScrolled(window.scrollY > 20)

      // 高亮当前板块
      const offsets = navigation
        .map((n) => {
          const el = document.getElementById(n.id)
          return el ? { id: n.id, top: el.getBoundingClientRect().top } : null
        })
        .filter(Boolean)

      const current = offsets.reduce((acc, item) => {
        if (item.top <= 140) return item.id
        return acc
      }, navigation[0].id)

      setActive(current)
    }

    window.addEventListener('scroll', onScroll, { passive: true })
    onScroll()
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  const scrollTo = (id) => {
    setMobileOpen(false)
    const el = document.getElementById(id)
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' })
    }
  }

  return (
    <>
      <header className={`nav${scrolled ? ' scrolled' : ''}`}>
        <div className="container nav-inner">
          <a href="#hero" className="nav-brand" onClick={(e) => { e.preventDefault(); scrollTo('hero') }}>
            {profile.name}
            <span>· {profile.title}</span>
          </a>

          <nav className="nav-links" aria-label="主导航">
            {navigation.map((item) => (
              <a
                key={item.id}
                href={`#${item.id}`}
                className={active === item.id ? 'active' : ''}
                onClick={(e) => { e.preventDefault(); scrollTo(item.id) }}
              >
                {item.label}
              </a>
            ))}
          </nav>

          <button
            className={`menu-btn${mobileOpen ? ' open' : ''}`}
            aria-label={mobileOpen ? '关闭菜单' : '打开菜单'}
            aria-expanded={mobileOpen}
            onClick={() => setMobileOpen((v) => !v)}
          >
            <span />
            <span />
            <span />
          </button>
        </div>
      </header>

      <nav className={`mobile-menu${mobileOpen ? ' open' : ''}`} aria-label="移动端导航">
        {navigation.map((item) => (
          <a
            key={item.id}
            href={`#${item.id}`}
            className={active === item.id ? 'active' : ''}
            onClick={(e) => { e.preventDefault(); scrollTo(item.id) }}
          >
            {item.label}
          </a>
        ))}
      </nav>
    </>
  )
}
