import { useCallback, useEffect, useRef, useState } from 'react'

// AI 音乐播放状态管理：卡片播放器与悬浮播放器共享同一份音频与状态，实现双向同步。
// 音频仅在用户点击播放后创建并调用 play()，禁止自动播放；不全局循环、不作为背景音乐。
export function useAiMusic(audioSrc) {
  const audioRef = useRef(null)
  const [playing, setPlaying] = useState(false)
  const [currentTime, setCurrentTime] = useState(0)
  const [duration, setDuration] = useState(0)
  const [visible, setVisible] = useState(false) // 悬浮播放器是否显示（首次播放后常驻）

  const ensureAudio = useCallback(() => {
    if (!audioRef.current) {
      const audio = new Audio(audioSrc)
      audio.preload = 'metadata'
      audio.addEventListener('loadedmetadata', () => setDuration(audio.duration || 0))
      audio.addEventListener('timeupdate', () => setCurrentTime(audio.currentTime))
      audio.addEventListener('play', () => setPlaying(true))
      audio.addEventListener('pause', () => setPlaying(false))
      audio.addEventListener('ended', () => {
        setPlaying(false)
        setCurrentTime(0)
        audio.currentTime = 0
      })
      audioRef.current = audio
    }
    return audioRef.current
  }, [audioSrc])

  // 播放 / 暂停（仅在用户点击后触发）
  const toggle = useCallback(() => {
    const audio = ensureAudio()
    if (audio.paused) {
      audio.play().catch(() => {})
      setVisible(true)
    } else {
      audio.pause()
    }
  }, [ensureAudio])

  // 跳转到指定时间（进度条点击）
  const seek = useCallback((time) => {
    const audio = audioRef.current
    if (!audio || !Number.isFinite(time)) return
    audio.currentTime = Math.min(Math.max(0, time), audio.duration || 0)
    setCurrentTime(audio.currentTime)
  }, [])

  // 组件卸载时释放音频资源
  useEffect(() => {
    return () => {
      if (audioRef.current) {
        audioRef.current.pause()
        audioRef.current.src = ''
        audioRef.current = null
      }
    }
  }, [])

  return { playing, currentTime, duration, visible, toggle, seek }
}
