import { useEffect, useRef } from 'react'
import { useReducedMotion } from '../hooks/useReducedMotion'

/**
 * 暗色地质风漂浮背景。
 * - 桌面端元素较多，移动端自动降量避免卡顿。
 * - 元素为小圆点、短线、小十字，颜色为暖白/琥珀低透明度。
 * - 鼠标靠近时产生轻微吸引效果。
 */
export function ParticleBackground() {
  const canvasRef = useRef(null)
  const reduced = useReducedMotion()

  useEffect(() => {
    if (reduced) return

    const canvas = canvasRef.current
    if (!canvas) return

    const ctx = canvas.getContext('2d')
    if (!ctx) return

    let width = 0
    let height = 0
    let particles = []
    let raf = 0
    let dpr = 1

    const mouse = { x: -1000, y: -1000 }

    const isTouch = window.matchMedia('(pointer: coarse)').matches
    const isMobile = window.innerWidth < 768 || isTouch

    // 移动端数量大幅降低
    const count = isMobile ? 22 : 56
    const mouseDistance = isMobile ? 100 : 160

    const colors = [
      'rgba(245, 240, 230, ',
      'rgba(232, 112, 42, ',
      'rgba(180, 140, 100, '
    ]

    class Particle {
      constructor() {
        this.reset()
      }

      reset() {
        this.x = Math.random() * width
        this.y = Math.random() * height
        this.vx = (Math.random() - 0.5) * (isMobile ? 0.25 : 0.42)
        this.vy = (Math.random() - 0.5) * (isMobile ? 0.25 : 0.42)
        this.baseAlpha = Math.random() * 0.22 + 0.12
        this.alpha = this.baseAlpha
        this.size = Math.random() * (isMobile ? 2 : 3) + 1.2
        this.rotation = Math.random() * Math.PI * 2
        this.rotSpeed = (Math.random() - 0.5) * 0.01
        // 0: 圆点, 1: 短线, 2: 小十字
        this.shape = Math.random() < 0.55 ? 0 : Math.random() < 0.8 ? 1 : 2
        this.colorBase = colors[Math.floor(Math.random() * colors.length)]
      }

      update() {
        this.x += this.vx
        this.y += this.vy
        this.rotation += this.rotSpeed

        // 边界反弹
        if (this.x < 0 || this.x > width) this.vx *= -1
        if (this.y < 0 || this.y > height) this.vy *= -1

        // 鼠标影响：轻柔吸引
        const dx = mouse.x - this.x
        const dy = mouse.y - this.y
        const dist = Math.sqrt(dx * dx + dy * dy)
        if (dist < mouseDistance && dist > 0) {
          const force = (mouseDistance - dist) / mouseDistance
          const angle = Math.atan2(dy, dx)
          this.vx += Math.cos(angle) * force * 0.012
          this.vy += Math.sin(angle) * force * 0.012
          this.alpha = Math.min(this.baseAlpha + force * 0.18, 0.55)
        } else {
          this.alpha += (this.baseAlpha - this.alpha) * 0.05
        }

        // 限速
        const speed = Math.sqrt(this.vx * this.vx + this.vy * this.vy)
        const maxSpeed = isMobile ? 1 : 1.5
        if (speed > maxSpeed) {
          this.vx = (this.vx / speed) * maxSpeed
          this.vy = (this.vy / speed) * maxSpeed
        }
      }

      draw() {
        ctx.save()
        ctx.translate(this.x, this.y)
        ctx.rotate(this.rotation)
        ctx.fillStyle = `${this.colorBase}${this.alpha})`
        ctx.strokeStyle = `${this.colorBase}${this.alpha})`
        ctx.lineWidth = 1.5
        ctx.lineCap = 'round'

        if (this.shape === 0) {
          // 手绘小圆点
          ctx.beginPath()
          ctx.arc(0, 0, this.size * 0.6, 0, Math.PI * 2)
          ctx.fill()
        } else if (this.shape === 1) {
          // 短线
          ctx.beginPath()
          ctx.moveTo(-this.size, 0)
          ctx.lineTo(this.size, 0)
          ctx.stroke()
        } else {
          // 小十字
          ctx.beginPath()
          ctx.moveTo(-this.size * 0.7, 0)
          ctx.lineTo(this.size * 0.7, 0)
          ctx.moveTo(0, -this.size * 0.7)
          ctx.lineTo(0, this.size * 0.7)
          ctx.stroke()
        }

        ctx.restore()
      }
    }

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2)
      width = canvas.offsetWidth
      height = canvas.offsetHeight
      canvas.width = width * dpr
      canvas.height = height * dpr
      ctx.scale(dpr, dpr)

      if (particles.length === 0) {
        for (let i = 0; i < count; i++) {
          particles.push(new Particle())
        }
      }
    }

    const animate = () => {
      ctx.clearRect(0, 0, width, height)

      particles.forEach((p) => {
        p.update()
        p.draw()
      })

      raf = requestAnimationFrame(animate)
    }

    const onMouseMove = (e) => {
      const rect = canvas.getBoundingClientRect()
      mouse.x = e.clientX - rect.left
      mouse.y = e.clientY - rect.top
    }

    const onMouseLeave = () => {
      mouse.x = -1000
      mouse.y = -1000
    }

    resize()
    animate()

    window.addEventListener('resize', resize)
    canvas.addEventListener('mousemove', onMouseMove)
    canvas.addEventListener('mouseleave', onMouseLeave)

    return () => {
      cancelAnimationFrame(raf)
      window.removeEventListener('resize', resize)
      canvas.removeEventListener('mousemove', onMouseMove)
      canvas.removeEventListener('mouseleave', onMouseLeave)
    }
  }, [reduced])

  if (reduced) return null

  return <canvas ref={canvasRef} className="hero-canvas" aria-hidden="true" />
}
