import { useEffect, useState } from 'react'

interface DigTransitionProps {
  active: boolean
  onDone?: () => void
}

export function DigTransition({ active, onDone }: DigTransitionProps) {
  const [phase, setPhase] = useState<'idle' | 'digging' | 'done'>('idle')

  useEffect(() => {
    if (!active) return
    setPhase('digging')
    const t1 = setTimeout(() => setPhase('done'), 1100)
    const t2 = setTimeout(() => {
      setPhase('idle')
      onDone?.()
    }, 1600)
    return () => {
      clearTimeout(t1)
      clearTimeout(t2)
    }
  }, [active, onDone])

  if (phase === 'idle') return null

  return (
    <div
      className={`fixed inset-0 z-[1200] pointer-events-none flex flex-col justify-center transition-opacity duration-500 ${
        phase === 'done' ? 'opacity-0' : 'opacity-100'
      }`}
      aria-hidden="true"
    >
      {[...Array(8)].map((_, i) => (
        <div
          key={i}
          className="absolute left-0 right-0 h-[14vh] strata-layer"
          style={{
            top: `${i * 13}vh`,
            background: `linear-gradient(180deg, rgba(20,20,20,0.95) 0%, rgba(30,22,16,0.92) 100%)`,
            borderTop: '1px solid rgba(232,112,42,0.25)',
            transform: phase === 'digging' ? 'translateY(120vh)' : 'translateY(0)',
            transition: `transform 0.85s cubic-bezier(0.16, 1, 0.3, 1) ${i * 0.05}s`,
          }}
        />
      ))}
      <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/60" />
    </div>
  )
}
