import { useTilt } from '../hooks/useTilt'

/**
 * 带 3D 倾斜与光影跟随的玻璃卡片。
 * 内部通过 ref 监听鼠标移动；移动端自动无效果。
 */
export function TiltCard({ children, className = '', intensity = 6 }) {
  const ref = useTilt(intensity)

  return (
    <div ref={ref} className={`glass-card tilt-card${className ? ` ${className}` : ''}`}>
      {children}
    </div>
  )
}
