import { useEffect, useRef, useState } from 'react'
import { gsap } from 'gsap'
import { Menu } from 'lucide-react'

const NAV_ITEMS = [
  { id: 'hero', label: 'About' },
  { id: 'education', label: 'Education' },
  { id: 'practice', label: 'Practice' },
  { id: 'skills', label: 'Skills' },
  { id: 'projects', label: 'Projects' },
  { id: 'contact', label: 'Contact' },
]

const BG_IMAGE_1 =
  'https://images.higgs.ai/?default=1&output=webp&url=https%3A%2F%2Fd8j0ntlcm91z4.cloudfront.net%2Fuser_38xzZboKViGWJOttwIXH07lWA1P%2Fhf_20260609_195923_b0ba8ace-1d1d-4f2c-9a28-1ab84b330680.png&w=1280&q=85'
const BG_IMAGE_2 =
  'https://images.higgs.ai/?default=1&output=webp&url=https%3A%2F%2Fd8j0ntlcm91z4.cloudfront.net%2Fuser_38xzZboKViGWJOttwIXH07lWA1P%2Fhf_20260609_201152_bba90a12-bf12-459f-91f0-51f237dbaf3b.png&w=1280&q=85'

const SPOTLIGHT_R = 260

interface LithosHeroProps {
  onStartDigging?: () => void
}

interface RevealLayerProps {
  image: string
  cursorX: number
  cursorY: number
}

function RevealLayer({ image, cursorX, cursorY }: RevealLayerProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [maskUrl, setMaskUrl] = useState<string>('')

  const drawMask = () => {
    const canvas = canvasRef.current
    if (!canvas) return

    if (canvas.width === 0 || canvas.height === 0) {
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
    }

    const ctx = canvas.getContext('2d')
    if (!ctx) return

    ctx.clearRect(0, 0, canvas.width, canvas.height)

    const gradient = ctx.createRadialGradient(
      cursorX,
      cursorY,
      0,
      cursorX,
      cursorY,
      SPOTLIGHT_R
    )
    gradient.addColorStop(0, 'rgba(255, 255, 255, 1)')
    gradient.addColorStop(0.4, 'rgba(255, 255, 255, 1)')
    gradient.addColorStop(0.6, 'rgba(255, 255, 255, 0.75)')
    gradient.addColorStop(0.75, 'rgba(255, 255, 255, 0.4)')
    gradient.addColorStop(0.88, 'rgba(255, 255, 255, 0.12)')
    gradient.addColorStop(1, 'rgba(255, 255, 255, 0)')

    ctx.fillStyle = gradient
    ctx.beginPath()
    ctx.arc(cursorX, cursorY, SPOTLIGHT_R, 0, Math.PI * 2)
    ctx.fill()

    setMaskUrl(canvas.toDataURL())
  }

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return

    const handleResize = () => {
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
      drawMask()
    }

    handleResize()
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  useEffect(() => {
    drawMask()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cursorX, cursorY])

  return (
    <>
      <canvas
        ref={canvasRef}
        className="absolute inset-0 pointer-events-none opacity-0"
        aria-hidden="true"
      />
      <div
        className="absolute inset-0 bg-center bg-cover bg-no-repeat z-30 pointer-events-none"
        style={{
          backgroundImage: `url(${image})`,
          maskImage: maskUrl ? `url(${maskUrl})` : undefined,
          WebkitMaskImage: maskUrl ? `url(${maskUrl})` : undefined,
          maskSize: '100% 100%',
          WebkitMaskSize: '100% 100%',
        }}
      />
    </>
  )
}

const scrollTo = (id: string) => {
  const el = document.getElementById(id)
  if (el) el.scrollIntoView({ behavior: 'smooth' })
}

export function LithosHero({ onStartDigging }: LithosHeroProps) {
  const mouse = useRef({ x: -999, y: -999 })
  const smooth = useRef({ x: -999, y: -999 })
  const rafRef = useRef<number | null>(null)
  const [cursorPos, setCursorPos] = useState({ x: -999, y: -999 })
  const [activeNav, setActiveNav] = useState('lithos-hero')

  const line1Ref = useRef<HTMLSpanElement>(null)
  const line2Ref = useRef<HTMLSpanElement>(null)
  const subtitleRef = useRef<HTMLDivElement>(null)
  const ctaRef = useRef<HTMLDivElement>(null)
  const navRef = useRef<HTMLElement>(null)

  // Opening animation
  useEffect(() => {
    const ctx = gsap.context(() => {
      const tl = gsap.timeline({ defaults: { ease: 'power3.out' } })

      tl.fromTo(
        '.hero-base-img',
        { scale: 1.18, opacity: 0 },
        { scale: 1, opacity: 1, duration: 1.8 }
      )
        .fromTo(
          line1Ref.current,
          { y: 120, opacity: 0, skewY: 8, clipPath: 'inset(100% 0 0 0)' },
          { y: 0, opacity: 1, skewY: 0, clipPath: 'inset(0% 0 0 0)', duration: 1.2 },
          0.3
        )
        .fromTo(
          line2Ref.current,
          { y: 120, opacity: 0, skewY: 8, clipPath: 'inset(100% 0 0 0)' },
          { y: 0, opacity: 1, skewY: 0, clipPath: 'inset(0% 0 0 0)', duration: 1.2 },
          0.48
        )
        .fromTo(
          subtitleRef.current,
          { y: 40, opacity: 0 },
          { y: 0, opacity: 1, duration: 1 },
          0.85
        )
        .fromTo(
          ctaRef.current,
          { y: 50, opacity: 0, scale: 0.92 },
          { y: 0, opacity: 1, scale: 1, duration: 0.9 },
          0.95
        )
        .fromTo(
          navRef.current,
          { y: -30, opacity: 0 },
          { y: 0, opacity: 1, duration: 0.9 },
          0.2
        )
    })

    return () => ctx.revert()
  }, [])

  // Mouse tracking for hero spotlight
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      mouse.current = { x: e.clientX, y: e.clientY }
      if (smooth.current.x === -999) {
        smooth.current = { x: e.clientX, y: e.clientY }
      }
    }

    const animate = () => {
      smooth.current.x += (mouse.current.x - smooth.current.x) * 0.1
      smooth.current.y += (mouse.current.y - smooth.current.y) * 0.1
      setCursorPos({ x: smooth.current.x, y: smooth.current.y })
      rafRef.current = requestAnimationFrame(animate)
    }

    window.addEventListener('mousemove', handleMouseMove)
    rafRef.current = requestAnimationFrame(animate)

    return () => {
      window.removeEventListener('mousemove', handleMouseMove)
      if (rafRef.current) cancelAnimationFrame(rafRef.current)
    }
  }, [])

  // Scroll spy
  useEffect(() => {
    const ids = ['lithos-hero', ...NAV_ITEMS.map((i) => i.id)]
    const onScroll = () => {
      const scrollY = window.scrollY + window.innerHeight * 0.35
      let current = 'lithos-hero'
      for (const id of ids) {
        const el = document.getElementById(id)
        if (el && el.offsetTop <= scrollY) {
          current = id
        }
      }
      setActiveNav(current)
    }
    window.addEventListener('scroll', onScroll, { passive: true })
    onScroll()
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  return (
    <div
      className="min-h-screen bg-black tracking-[-0.02em]"
      style={{ fontFamily: "'Inter', sans-serif" }}
    >
      <section
        id="lithos-hero"
        className="relative w-full overflow-hidden h-screen bg-black"
        style={{ height: '100dvh' }}
      >
        {/* Base image */}
        <div
          className="hero-base-img absolute inset-0 bg-center bg-cover bg-no-repeat z-10"
          style={{ backgroundImage: `url(${BG_IMAGE_1})` }}
        />

        {/* Reveal layer */}
        <RevealLayer
          image={BG_IMAGE_2}
          cursorX={cursorPos.x}
          cursorY={cursorPos.y}
        />

        {/* Heading */}
        <div className="absolute top-[18%] sm:top-[16%] md:top-[14%] left-0 right-0 flex flex-col items-center text-center px-5 pointer-events-none z-50">
          <h1 className="text-white leading-[0.95]">
            <span
              ref={line1Ref}
              className="block font-playfair italic font-normal text-5xl sm:text-7xl md:text-8xl"
              style={{ letterSpacing: '-0.05em' }}
            >
              Layers hold
            </span>
            <span
              ref={line2Ref}
              className="block font-normal text-5xl sm:text-7xl md:text-8xl -mt-1"
              style={{ letterSpacing: '-0.08em' }}
            >
              tales of time
            </span>
          </h1>
        </div>

        {/* Bottom-left paragraph */}
        <div
          ref={subtitleRef}
          className="hidden sm:block absolute bottom-14 left-10 md:left-14 max-w-[260px] z-50 bottom-left-block"
        >
          <p className="text-sm text-white/80 leading-relaxed">
            Every layer of sediment records a chapter of our planet, from ancient
            seabeds to drifting ash, layered across millions of years beneath us.
          </p>
        </div>

        {/* Bottom-right block */}
        <div
          ref={ctaRef}
          className="absolute bottom-10 sm:bottom-24 left-5 right-5 sm:left-auto sm:right-10 md:right-14 max-w-full sm:max-w-[260px] flex flex-col items-start gap-4 sm:gap-5 z-50 bottom-right-block"
        >
          <p className="text-xs sm:text-sm text-white/80 leading-relaxed">
            Our interactive maps let you peel back the crust to trace how stones,
            fossils, and deep time combine to shape the ground beneath your feet.
          </p>
          <button
            onClick={onStartDigging}
            className="bg-[#e8702a] hover:bg-[#d2611f] text-white text-sm sm:text-base font-medium px-8 py-3.5 sm:px-9 sm:py-4 rounded-full transition-all hover:scale-[1.03] active:scale-95 hover:shadow-lg hover:shadow-[#e8702a]/30"
          >
            Start Digging
          </button>
        </div>

        {/* Navigation */}
        <nav
          ref={navRef}
          className="absolute top-0 left-0 right-0 z-[1100] flex items-center justify-between p-4 sm:p-5"
        >
          {/* Left: logo + wordmark */}
          <button
            onClick={() => scrollTo('lithos-hero')}
            className="flex items-center gap-3"
          >
            <svg
              width="26"
              height="26"
              viewBox="0 0 256 256"
              fill="#ffffff"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path d="M 256 256 L 128 256 L 0 128 L 128 128 Z M 256 128 L 128 128 L 0 0 L 128 0 Z" />
            </svg>
            <span className="text-white text-2xl font-playfair italic">Lithos</span>
          </button>

          {/* Center pill */}
          <div className="hidden md:flex absolute left-1/2 -translate-x-1/2 bg-white/10 backdrop-blur-md border border-white/20 rounded-full px-2 py-2 items-center gap-1">
            {NAV_ITEMS.map((item) => {
              const isActive = activeNav === item.id
              return (
                <button
                  key={item.id}
                  onClick={() => scrollTo(item.id)}
                  className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all duration-300 ${
                    isActive
                      ? 'bg-white text-gray-900'
                      : 'text-white/80 hover:bg-white/15 hover:text-white'
                  }`}
                >
                  {item.label}
                </button>
              )
            })}
          </div>

          {/* Right: desktop CTA */}
          <div className="hidden md:block">
            <button
              onClick={() => scrollTo('contact')}
              className="bg-white/10 border border-white/20 text-white text-sm font-semibold px-6 py-2.5 rounded-full hover:bg-white/20 transition-colors"
            >
              Let’s talk
            </button>
          </div>

          {/* Mobile hamburger */}
          <button
            className="md:hidden text-white p-1"
            aria-label="Open menu"
            onClick={() => scrollTo('hero')}
          >
            <Menu size={24} />
          </button>
        </nav>
      </section>
    </div>
  )
}
