import { useRef, useState } from 'react'

interface RockProps {
  size: number
  rotation: number
  variant: number
  top?: string
  left?: string
  right?: string
  bottom?: string
}

const PATHS = [
  'M20,8 L36,14 L44,28 L38,46 L22,52 L8,44 L4,26 L12,12 Z',
  'M16,4 L34,10 L48,24 L42,42 L28,54 L10,48 L2,30 L8,14 Z',
  'M22,6 L40,18 L46,36 L32,50 L14,46 L4,28 L12,12 Z',
  'M18,2 L38,8 L50,26 L44,44 L26,54 L6,42 L2,22 L10,10 Z',
]

function Rock({ size, rotation, variant, top, left, right, bottom }: RockProps) {
  const ref = useRef<HTMLDivElement>(null)
  const [hover, setHover] = useState(false)
  const [pos, setPos] = useState({ x: 50, y: 50 })

  const path = PATHS[variant % PATHS.length]

  const handleMove = (e: React.MouseEvent) => {
    if (!ref.current) return
    const rect = ref.current.getBoundingClientRect()
    const x = ((e.clientX - rect.left) / rect.width) * 100
    const y = ((e.clientY - rect.top) / rect.height) * 100
    setPos({ x, y })
  }

  return (
    <div
      ref={ref}
      className="absolute pointer-events-auto rock-item"
      style={{
        width: size,
        height: size,
        top,
        left,
        right,
        bottom,
        transform: `rotate(${rotation}deg)`,
        '--mx': `${pos.x}%`,
        '--my': `${pos.y}%`,
      } as React.CSSProperties}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      onMouseMove={handleMove}
    >
      <svg
        viewBox="0 0 52 56"
        fill="none"
        className="w-full h-full drop-shadow-md"
        style={{ filter: 'drop-shadow(2px 3px 3px rgba(0,0,0,0.4))' }}
      >
        {/* base stone */}
        <path
          d={path}
          fill="#2c2824"
          stroke="rgba(245,240,230,0.12)"
          strokeWidth="1.2"
        />
        {/* lively reveal layer */}
        <g
          style={{
            opacity: hover ? 1 : 0,
            transition: 'opacity 0.35s ease-out',
            maskImage: `radial-gradient(circle at var(--mx) var(--my), black 0%, black 38%, transparent 72%)`,
            WebkitMaskImage: `radial-gradient(circle at var(--mx) var(--my), black 0%, black 38%, transparent 72%)`,
          }}
        >
          <defs>
            <linearGradient id={`moss-${variant}`} x1="0" y1="0" x2="52" y2="56" gradientUnits="userSpaceOnUse">
              <stop offset="0%" stopColor="#65a30d" />
              <stop offset="45%" stopColor="#16a34a" />
              <stop offset="100%" stopColor="#f59e0b" />
            </linearGradient>
          </defs>
          <path
            d={path}
            fill={`url(#moss-${variant})`}
          />
        </g>
      </svg>
    </div>
  )
}

interface RockBorderProps {
  count?: number
  seed?: number
}

export function RockBorder({ count = 5, seed = 1 }: RockBorderProps) {
  const rocks = generateRocks(count, seed)

  return (
    <div className="absolute -inset-6 pointer-events-none" aria-hidden="true">
      {rocks.map((rock, idx) => (
        <Rock key={idx} {...rock} />
      ))}
    </div>
  )
}

function generateRocks(count: number, seed: number) {
  const rng = mulberry32(seed)
  const rocks: RockProps[] = []

  for (let i = 0; i < count; i++) {
    const edge = Math.floor(rng() * 4) // 0:top, 1:right, 2:bottom, 3:left
    const size = 28 + rng() * 32
    const rotation = rng() * 360
    const variant = Math.floor(rng() * PATHS.length)
    const offset = 8 + rng() * 84 // percentage along the edge

    let rock: RockProps = { size, rotation, variant }

    if (edge === 0) {
      rock = { ...rock, top: '-18px', left: `${offset}%` }
    } else if (edge === 1) {
      rock = { ...rock, right: '-18px', top: `${offset}%` }
    } else if (edge === 2) {
      rock = { ...rock, bottom: '-18px', left: `${offset}%` }
    } else {
      rock = { ...rock, left: '-18px', top: `${offset}%` }
    }

    rocks.push(rock)
  }

  return rocks
}

function mulberry32(a: number) {
  return function () {
    let t = (a += 0x6d2b79f5)
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
