import { useState } from 'react'
import { strengths, experiences } from '../data/profile'
import { RockBorder } from './RockBorder'
import { SectionHeader } from './SectionHeader'
import { TiltCard } from './TiltCard'

export function Skills() {
  const [activeCert, setActiveCert] = useState(null)

  return (
    <section id="skills" className="section">
      <RockBorder count={6} seed={6} />
      <div className="container">
        <SectionHeader
          label="Skills"
          title="技能"
          highlight="证书"
          desc="核心能力、技术栈与专业认证。"
        />

        <TiltCard className="skill-tags-card gsap-card gsap-initial">
          <h3>核心能力标签</h3>
          <div className="tags-cloud">
            {strengths.tags.map((tag) => (
              <span key={tag} className="tag">{tag}</span>
            ))}
          </div>
        </TiltCard>

        <div className="skills-grid">
          {strengths.skills.map((group) => (
            <TiltCard key={group.category} className="skill-card gsap-card gsap-initial">
              <h4>{group.category}</h4>
              <div className="skill-items">
                {group.items.map((item) => (
                  <span key={item} className="tag">{item}</span>
                ))}
              </div>
            </TiltCard>
          ))}
        </div>

        <div className="skills-subheader">
          <h3 className="skills-subheading">专业认证</h3>
        </div>

        <div className="cert-grid">
          {experiences.certificates.map((cert) => (
            <TiltCard key={cert.id} className="cert-card gsap-card gsap-initial">
              <button
                className="cert-inner"
                onClick={() => setActiveCert(cert)}
                aria-label={`放大查看 ${cert.name}`}
              >
                <div className="cert-thumb">
                  <img src={cert.image} alt={cert.name} loading="lazy" />
                </div>
                <div className="cert-info">
                  <p className="name">{cert.name}</p>
                  <p className="date">{cert.date}</p>
                  <p className="brief">{cert.brief}</p>
                </div>
              </button>
            </TiltCard>
          ))}
        </div>
      </div>

      {activeCert && (
        <div
          className="cert-modal"
          onClick={() => setActiveCert(null)}
          role="dialog"
          aria-modal="true"
          aria-label={activeCert.name}
        >
          <div className="cert-modal-mask" />
          <div className="cert-modal-content" onClick={(e) => e.stopPropagation()}>
            <img src={activeCert.image} alt={activeCert.name} />
            <div className="cert-modal-info">
              <p className="name">{activeCert.name}</p>
              <p className="date">{activeCert.date}</p>
              <p className="brief">{activeCert.brief}</p>
            </div>
            <button
              className="cert-modal-close"
              onClick={() => setActiveCert(null)}
              aria-label="关闭"
            >
              ×
            </button>
          </div>
        </div>
      )}
    </section>
  )
}