import { useEffect, useRef, useState } from 'react'
import { Play, Pause } from './Icons'

// 悬浮播放器：默认隐藏，卡片首次播放后常驻显示。
// 点击窗口切换跟随模式：点击进入跟随（窗口随鼠标/手指移动），再次点击固定位置；
// 跟随过程中窗口始终限制在浏览器视口内，播放按钮不受跟随逻辑影响。
export function FloatingPlayer({ song, playing, onToggle }) {
  const ref = useRef(null)
  const [following, setFollowing] = useState(false)
  // 触屏拖动结束时会触发一次 click，用它抑制误切换
  const suppressClick = useRef(false)

  useEffect(() => {
    if (!following) return
    const el = ref.current
    if (!el) return

    // 窗口中心跟随光标，并限制在视口内，不能拖出屏幕边界
    const moveTo = (clientX, clientY) => {
      const rect = el.getBoundingClientRect()
      const x = Math.min(
        Math.max(0, clientX - rect.width / 2),
        Math.max(0, window.innerWidth - rect.width)
      )
      const y = Math.min(
        Math.max(0, clientY - rect.height / 2),
        Math.max(0, window.innerHeight - rect.height)
      )
      el.style.right = 'auto'
      el.style.bottom = 'auto'
      el.style.left = `${x}px`
      el.style.top = `${y}px`
    }

    const onMouseMove = (e) => moveTo(e.clientX, e.clientY)
    const onTouchMove = (e) => {
      const t = e.touches[0]
      if (t) {
        suppressClick.current = true
        moveTo(t.clientX, t.clientY)
      }
    }

    window.addEventListener('mousemove', onMouseMove)
    window.addEventListener('touchmove', onTouchMove, { passive: true })
    return () => {
      window.removeEventListener('mousemove', onMouseMove)
      window.removeEventListener('touchmove', onTouchMove)
    }
  }, [following])

  const handleClick = (e) => {
    // 触屏拖动产生的 click 不参与切换
    if (suppressClick.current) {
      suppressClick.current = false
      return
    }
    // 播放按钮交由其自身的 onClick 处理，不参与跟随模式切换
    if (e.target.closest('button')) return
    setFollowing((v) => !v)
  }

  return (
    <div
      ref={ref}
      className={`floating-player${following ? ' fp-dragging' : ''}`}
      onClick={handleClick}
    >
      <button
        type="button"
        className="floating-player-btn"
        onClick={onToggle}
        aria-label={playing ? '暂停' : '播放'}
      >
        {playing ? <Pause /> : <Play />}
      </button>
      <span className="floating-player-song">《{song}》</span>
    </div>
  )
}
