import { useEffect, useState } from 'react'
import { projects, aiWorks } from '../data/profile'
import { RockBorder } from './RockBorder'
import { SectionHeader } from './SectionHeader'
import { TiltCard } from './TiltCard'
import { FloatingPlayer } from './FloatingPlayer'
import { useAiMusic } from '../hooks/useAiMusic'
import { Github, ExternalLink, ImagePlaceholder, Play, Pause } from './Icons'
// PDF.js 主体改为懒加载（首次渲染 PDF 缩略图时才动态导入），
// 避免把 1MB+ 的 pdf.mjs 打进首屏主 bundle；
// worker 通过 ?url 导入，Vite 会拷贝到 assets 并生成相对路径，兼容 GitHub Pages 子目录。
import pdfWorkerUrl from 'pdfjs-dist/legacy/build/pdf.worker.min.mjs?url'

// worker 地址只需设置一次（幂等）
let pdfjsLibPromise = null
async function getPdfjs() {
  if (!pdfjsLibPromise) {
    const pdfjsLib = await import('pdfjs-dist/legacy/build/pdf.mjs')
    pdfjsLib.GlobalWorkerOptions.workerSrc = pdfWorkerUrl
    pdfjsLibPromise = pdfjsLib
  }
  return pdfjsLibPromise
}

// 秒数格式化为 m:ss
function formatTime(sec) {
  if (!Number.isFinite(sec) || sec <= 0) return '0:00'
  const m = Math.floor(sec / 60)
  const s = Math.floor(sec % 60)
    .toString()
    .padStart(2, '0')
  return `${m}:${s}`
}

// PDF 前 3 页堆叠预览：渲染缩略图，点击堆叠区域循环切换 1→2→3→1
function PdfStack({ pdfUrl }) {
  const [pages, setPages] = useState([])
  const [current, setCurrent] = useState(0)

  useEffect(() => {
    let cancelled = false

    async function load() {
      try {
        const pdfjsLib = await getPdfjs()
        const pdf = await pdfjsLib.getDocument({ url: pdfUrl }).promise
        const list = []
        const count = Math.min(3, pdf.numPages)
        const targetWidth = 150

        for (let i = 1; i <= count; i++) {
          const page = await pdf.getPage(i)
          const base = page.getViewport({ scale: 1 })
          const viewport = page.getViewport({ scale: targetWidth / base.width })
          const canvas = document.createElement('canvas')
          canvas.width = viewport.width
          canvas.height = viewport.height
          const ctx = canvas.getContext('2d')
          await page.render({ canvasContext: ctx, viewport }).promise
          list.push({ src: canvas.toDataURL('image/png'), width: viewport.width, height: viewport.height })
        }

        if (!cancelled) setPages(list)
      } catch (err) {
        console.error('PDF 预览加载失败', err)
        if (!cancelled) setPages([{ src: '', width: 0, height: 0 }])
      }
    }

    load()
    return () => {
      cancelled = true
    }
  }, [pdfUrl])

  // 加载中 / 加载失败的占位
  if (!pages.length) {
    return (
      <div className="ai-pdf-panel">
        <div className="ai-pdf-loading">PDF 加载中…</div>
      </div>
    )
  }

  if (!pages[0].src) {
    return (
      <div className="ai-pdf-panel">
        <div className="ai-pdf-loading">PDF 加载失败</div>
      </div>
    )
  }

  const { width, height } = pages[current]
  const back = pages[(current + 1) % 3]
  const mid = pages[(current + 2) % 3]

  return (
    <div className="ai-pdf-panel">
      <button
        type="button"
        className="ai-pdf-stack"
        style={{ width, height }}
        onClick={() => setCurrent((c) => (c + 1) % 3)}
        aria-label="切换PDF页面预览"
      >
        <img
          className="ai-pdf-page ai-pdf-page--back"
          src={back.src}
          alt={`plan.pdf 第 ${((current + 1) % 3) + 1} 页`}
          loading="lazy"
        />
        <img
          className="ai-pdf-page ai-pdf-page--mid"
          src={mid.src}
          alt={`plan.pdf 第 ${((current + 2) % 3) + 1} 页`}
          loading="lazy"
        />
        <img
          className="ai-pdf-page ai-pdf-page--front"
          key={current}
          src={pages[current].src}
          alt={`plan.pdf 第 ${current + 1} 页`}
        />
      </button>
      <a className="ai-pdf-open" href={pdfUrl} target="_blank" rel="noopener noreferrer">
        查看完整PDF
      </a>
    </div>
  )
}

export function Projects() {
  const [expanded, setExpanded] = useState(null)
  const music = useAiMusic(aiWorks.music.audio)

  const toggle = (id) => setExpanded((v) => (v === id ? null : id))

  const progressPct = music.duration
    ? Math.min(100, (music.currentTime / music.duration) * 100)
    : 0

  const onProgressClick = (e) => {
    const rect = e.currentTarget.getBoundingClientRect()
    const ratio = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width))
    music.seek(ratio * music.duration)
  }

  return (
    <section id="projects" className="section">
      <RockBorder count={6} seed={3} />
      <div className="container">
        <SectionHeader
          label="Projects"
          title="项目"
          highlight="作品"
          desc="聚焦可落地的技术实践，源码与演示按需开放。"
        />

        <div className="projects-grid">
          {projects.map((proj) => {
            const isOpen = expanded === proj.id
            return (
              <TiltCard key={proj.id} className="project-card gsap-card gsap-initial" intensity={5}>
                <div className="project-thumb">
                  {proj.image ? (
                    <img
                      className="gsap-img-reveal gsap-initial"
                      src={proj.image}
                      alt={proj.title}
                      loading="lazy"
                    />
                  ) : (
                    <div className="project-thumb-placeholder gsap-img-reveal gsap-initial">
                      <ImagePlaceholder />
                      <span>项目图片插槽</span>
                    </div>
                  )}
                </div>

                <div className="project-body">
                  <h3>{proj.title}</h3>
                  <div className="project-tags">
                    {proj.tags.map((tag) => (
                      <span key={tag} className="tag">{tag}</span>
                    ))}
                  </div>
                  <p className="project-desc">{proj.description}</p>

                  {proj.highlights && (
                    <button
                      className="project-collapse"
                      onClick={() => toggle(proj.id)}
                      aria-expanded={isOpen}
                    >
                      <span>核心亮点</span>
                      <svg
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2"
                        width="14"
                        height="14"
                        className={`collapse-icon${isOpen ? ' open' : ''}`}
                      >
                        <polyline points="6 9 12 15 18 9" />
                      </svg>
                    </button>
                  )}

                  {isOpen && proj.highlights && (
                    <ul className="project-highlights">
                      {proj.highlights.map((h, idx) => (
                        <li key={idx}>{h}</li>
                      ))}
                    </ul>
                  )}

                  <div className="project-actions">
                    {proj.github ? (
                      <a
                        className="btn btn-primary"
                        href={proj.github}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <Github />
                        源码
                      </a>
                    ) : (
                      <span className="btn btn-ghost" aria-disabled="true">
                        <Github />
                        源码待开源
                      </span>
                    )}
                    {proj.github && (
                      <a
                        className="btn btn-ghost"
                        href={proj.github}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <ExternalLink />
                        查看详情
                      </a>
                    )}
                  </div>
                </div>
              </TiltCard>
            )
          })}
        </div>

        {/* AI 创意多媒体作品 */}
        <div className="ai-works">
          <div className="ai-works-head">
            <h3 className="ai-works-title">{aiWorks.category}</h3>
          </div>

          <div className="ai-works-grid">
            <div className="ai-work-card glass-card gsap-card gsap-initial">
              <div className="ai-work-icon ai-work-icon--music">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" width="22" height="22">
                  <circle cx="8" cy="18" r="3" />
                  <circle cx="18" cy="16" r="3" />
                  <path d="M11 18V5l10-2v11" />
                </svg>
              </div>
              <h4>{aiWorks.music.title}</h4>
              <div className="ai-music-placeholder">
                <button
                  type="button"
                  className="ai-play-btn"
                  onClick={music.toggle}
                  aria-label={music.playing ? '暂停' : '播放'}
                >
                  {music.playing ? <Pause /> : <Play />}
                </button>
                <div className="ai-music-main">
                  <span className="ai-music-song">《{aiWorks.music.song}》</span>
                  <div className="ai-music-progress" onClick={onProgressClick}>
                    <div
                      className="ai-music-progress-fill"
                      style={{ width: `${progressPct}%` }}
                    />
                  </div>
                </div>
                <span className="ai-music-time">
                  {formatTime(music.currentTime)} / {formatTime(music.duration)}
                </span>
              </div>
            </div>

            <div className="ai-work-card glass-card gsap-card gsap-initial ai-ppt-card">
              <div className="ai-ppt-info">
                <h4>{aiWorks.ppt.title}</h4>
                <p className="ai-work-note">{aiWorks.ppt.note}</p>
              </div>
              <PdfStack pdfUrl={aiWorks.ppt.pdf} />
            </div>
          </div>
        </div>
      </div>

      {/* 悬浮可拖拽播放器：首次播放后常驻，fixed 定位跨页面置顶 */}
      {music.visible && (
        <FloatingPlayer
          song={aiWorks.music.song}
          playing={music.playing}
          onToggle={music.toggle}
        />
      )}
    </section>
  )
}