import { Hero } from './components/Hero'
import { Education } from './components/Education'
import { Practice } from './components/Practice'
import { Skills } from './components/Skills'
import { Projects } from './components/Projects'
import { Contact } from './components/Contact'
import { LithosHero } from './components/LithosHero'
import { DigTransition } from './components/DigTransition'
import { Navigation } from './components/Navigation'
import { BackToTop } from './components/BackToTop'
import { useParallax } from './hooks/useParallax'
import { useAnimations } from './hooks/useAnimations'
import { useEffect, useRef, useState } from 'react'

function App() {
  const { ref: glowRef, offset: glowOffset } = useParallax(0.04)
  const [digging, setDigging] = useState(false)
  const [unlocked, setUnlocked] = useState(false)
  const contentRef = useRef<HTMLDivElement>(null)

  useAnimations(unlocked)

  useEffect(() => {
    document.documentElement.style.overflow = 'hidden'
    document.body.style.overflow = 'hidden'
    window.scrollTo(0, 0)
    return () => {
      document.documentElement.style.overflow = ''
      document.body.style.overflow = ''
    }
  }, [])

  const startDigging = () => {
    if (unlocked) return
    setDigging(true)
    // 等待彩蛋「挖掘」动画接近完成后再解锁并平滑滚动至正文顶部
    setTimeout(() => {
      setUnlocked(true)
      document.documentElement.style.overflow = ''
      document.body.style.overflow = ''
      if (contentRef.current) {
        contentRef.current.style.display = 'block'
      }
      requestAnimationFrame(() => {
        const el = document.getElementById('hero')
        if (el) {
          el.scrollIntoView({ behavior: 'smooth' })
        }
      })
    }, 900)
  }

  return (
    <>
      <LithosHero onStartDigging={startDigging} />
      {unlocked && <Navigation />}
      {unlocked && <BackToTop />}
      <div ref={contentRef} className="relative" style={{ display: 'none' }}>
        <div className="bg-grid" aria-hidden="true" />
        <div
          ref={glowRef}
          className="bg-glow parallax"
          style={{ transform: `translateY(${glowOffset}px)` }}
          aria-hidden="true"
        />
        <div className="film-grain" aria-hidden="true" />
        <div className="light-leak light-leak--top" aria-hidden="true" />
        <div className="light-leak light-leak--bottom" aria-hidden="true" />
        <div className="dust-particles" aria-hidden="true">
          <span />
          <span />
          <span />
          <span />
          <span />
          <span />
          <span />
          <span />
        </div>
        <main>
          <Hero />
          <Education />
          <Practice />
          <Skills />
          <Projects />
          <Contact />
        </main>
      </div>
      <DigTransition active={digging} onDone={() => setDigging(false)} />
    </>
  )
}

export default App