import { useEffect, useRef } from 'react'
import { gsap } from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'

gsap.registerPlugin(ScrollTrigger)

export function useAnimations(unlocked: boolean) {
  const ctxRef = useRef<gsap.Context | null>(null)

  useEffect(() => {
    if (!unlocked) return

    // wait one frame for layout
    const raf = requestAnimationFrame(() => {
      ScrollTrigger.refresh()

      ctxRef.current = gsap.context(() => {
        // Section titles: dramatic entrance
        gsap.utils.toArray<HTMLElement>('.section-title-gsap').forEach((title) => {
          gsap.fromTo(
            title,
            { y: 90, opacity: 0, skewY: 4 },
            {
              y: 0,
              opacity: 1,
              skewY: 0,
              duration: 1.1,
              ease: 'power3.out',
              scrollTrigger: {
                trigger: title,
                start: 'top 82%',
                toggleActions: 'play none none none',
              },
            }
          )
        })

        // Section descriptions
        gsap.utils.toArray<HTMLElement>('.section-desc-gsap').forEach((desc) => {
          gsap.fromTo(
            desc,
            { y: 40, opacity: 0 },
            {
              y: 0,
              opacity: 1,
              duration: 0.9,
              ease: 'power3.out',
              scrollTrigger: {
                trigger: desc,
                start: 'top 85%',
                toggleActions: 'play none none none',
              },
            }
          )
        })

        // Cards stagger via batch
        ScrollTrigger.batch('.gsap-card', {
          interval: 0.08,
          batchMax: 4,
          onEnter: (batch) => {
            gsap.fromTo(
              batch,
              { y: 70, opacity: 0, scale: 0.96 },
              {
                y: 0,
                opacity: 1,
                scale: 1,
                duration: 0.85,
                ease: 'power3.out',
                stagger: 0.12,
                overwrite: true,
                clearProps: 'transform',
              }
            )
          },
          start: 'top 88%',
        })

        // Image reveal / parallax
        gsap.utils.toArray<HTMLElement>('.gsap-img-reveal').forEach((img) => {
          gsap.fromTo(
            img,
            { y: 40, opacity: 0, clipPath: 'inset(12% 0 12% 0)' },
            {
              y: 0,
              opacity: 1,
              clipPath: 'inset(0% 0 0% 0)',
              duration: 1.1,
              ease: 'power3.out',
              scrollTrigger: {
                trigger: img,
                start: 'top 85%',
                toggleActions: 'play none none none',
              },
            }
          )

          // subtle parallax
          gsap.to(img, {
            y: -30,
            ease: 'none',
            scrollTrigger: {
              trigger: img,
              start: 'top bottom',
              end: 'bottom top',
              scrub: 1,
            },
          })
        })

        // Contact elements
        gsap.utils.toArray<HTMLElement>('.gsap-contact-item').forEach((item, i) => {
          gsap.fromTo(
            item,
            { y: 50, opacity: 0 },
            {
              y: 0,
              opacity: 1,
              duration: 0.9,
              ease: 'power3.out',
              delay: i * 0.1,
              scrollTrigger: {
                trigger: item,
                start: 'top 88%',
                toggleActions: 'play none none none',
              },
            }
          )
        })
      })
    })

    return () => {
      cancelAnimationFrame(raf)
      ctxRef.current?.revert()
      ctxRef.current = null
    }
  }, [unlocked])
}
